 return {
  labelFor:lab?.htmlFor, inputName:cpf?.getAttribute('name'), inputAria:cpf?.getAttribute('aria-label'),
  form:document.querySelector('form')?.outerHTML.slice(0,1500),
  focusStyle:(()=>{cpf.focus(); const s=getComputedStyle(cpf); return {active:document.activeElement.id,outline:s.outline,outlineOffset:s.outlineOffset,boxShadow:s.boxShadow}})(),
